	MaskSize.value = 0;
	MaskSize.min = 0;
	MaskSize.max = 1;
	MaskSize.isBoolean = false;
	MaskSize.matrixMode = 0;
	MaskSize.animationType = BABYLON.AnimatedInputBlockTypes.None;
	MaskSize.isConstant = false;
