	FloatPow.min = 0;
	FloatPow.max = 0;
	FloatPow.isBoolean = false;
	FloatPow.matrixMode = 0;
	FloatPow.animationType = BABYLON.AnimatedInputBlockTypes.None;
	FloatPow.isConstant = false;
	FloatPow.visibleInInspector = false;
	
	// MultiplyBlock
	var Multiply1 = new BABYLON.MultiplyBlock("Multiply");
	
	// VectorMergerBlock
	var VectorMerger1 = new BABYLON.VectorMergerBlock("VectorMerger");
	
	// RemapBlock
	var Remap1 = new BABYLON.RemapBlock("Remap");
