	var Multiply3 = new BABYLON.MultiplyBlock("Multiply");
	
	// OneMinusBlock
	var Oneminus2 = new BABYLON.OneMinusBlock("One minus");
	
	// VectorMergerBlock
	var VectorMerger2 = new BABYLON.VectorMergerBlock("VectorMerger");
	
	// LerpBlock
	var Lerp = new BABYLON.LerpBlock("Lerp");
	
	// TextureBlock
	var texBeauty = new BABYLON.TextureBlock("texBeauty");
	texBeauty.texture = Beauty;
	texBeauty.texture.wrapU = 1;
	texBeauty.texture.wrapV = 1;
	texBeauty.texture.uAng = 0;
	texBeauty.texture.vAng = 0;
	texBeauty.texture.wAng = 0;
	texBeauty.texture.uOffset = 0;
	texBeauty.texture.vOffset = 0;
	texBeauty.texture.uScale = 1;
	texBeauty.texture.vScale = 1;
	texBeauty.convertToGammaSpace = false;
	texBeauty.convertToLinearSpace = false;
	
	// InputBlock
	var uv = new BABYLON.InputBlock("uv");
	uv.setAsAttribute("uv");
	
	// TextureBlock
	var texWire = new BABYLON.TextureBlock("texWire");
	texWire.texture = Wire;
	texWire.texture.wrapU = 1;
	texWire.texture.wrapV = 1;
	texWire.texture.uAng = 0;
	texWire.texture.vAng = 0;
	texWire.texture.wAng = 0;
	texWire.texture.uOffset = 0;
	texWire.texture.vOffset = 0;
	texWire.texture.uScale = 1;
	texWire.texture.vScale = 1;
	texWire.convertToGammaSpace = false;
	texWire.convertToLinearSpace = false;
	
	// VectorSplitterBlock
	var VectorSplitter1 = new BABYLON.VectorSplitterBlock("VectorSplitter");
	
	// FragmentOutputBlock
	var FragmentOutput = new BABYLON.FragmentOutputBlock("FragmentOutput");
	
	// MultiplyBlock
	var Multiply4 = new BABYLON.MultiplyBlock("Multiply");
	
	// InputBlock
	var Alpha = new BABYLON.InputBlock("Alpha");
	Alpha.value = 1;
	Alpha.min = 0;
	Alpha.max = 1;
	Alpha.isBoolean = false;
	Alpha.matrixMode = 0;
	Alpha.animationType = BABYLON.AnimatedInputBlockTypes.None;
	Alpha.isConstant = false;
