//add and clear animations
function playAnimTo(anim,first,end){
      anim.goToAndPlay(first, end)  
      let stop = setInterval(()=>{
        if (anim.currentFrame > end-1){
         anim.pause(); 
          clearInterval(stop);
        }
      },10)
}

